//! `c3 pack` â€” build a reviewer pack (and its `.pack.json` sidecar) for the `http` engine
//! (milestone 7; milestone 7b consumes it). The pipeline lives in
//! [`crate::pack::reviewer`].

use std::path::PathBuf;

use clap::Args;

use crate::pack::reviewer::{self, PackOpts};
use crate::providers;

/// Arguments of `c3 pack`.
#[derive(Args, Debug, Default)]
pub struct PackArgs {
    /// The one-page brief file (path relative to the repo root, or absolute).
    #[arg(long)]
    pub brief: String,
    /// Focus file(s): path or glob, included in full (repeatable).
    #[arg(long)]
    pub focus: Vec<String>,
    /// Token budget for the periphery (0 = none).
    #[arg(long, default_value_t = 0)]
    pub budget: usize,
    /// Task slug whose `findings.json` supplies the open-findings snapshot.
    #[arg(long)]
    pub task: Option<String>,
    /// Output path for the pack; the `.pack.json` sidecar is written beside it.
    #[arg(long)]
    pub out: String,
    /// Where consultations are stored; a relative path resolves against the repo root.
    #[arg(long, default_value = ".collab")]
    pub collab_dir: String,
}

/// Build the reviewer pack and its sidecar. Returns the process exit code.
pub fn run(args: PackArgs) -> i32 {
    if args.out.trim().is_empty() {
        eprintln!("c3 pack: --out is required");
        return 1;
    }
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let repo_root = providers::resolve_repo_root(&cwd);
    let collab_root = providers::resolve_collab_root(&repo_root, &args.collab_dir);

    let out = PathBuf::from(&args.out);
    let opts = PackOpts {
        repo_root,
        collab_root,
        brief: PathBuf::from(&args.brief),
        focus: args.focus,
        budget: args.budget,
        task: args.task,
        out: out.clone(),
        max_file_size: 2 * 1024 * 1024,
    };

    let pack = match reviewer::build(&opts) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("c3 pack: {e}");
            return 1;
        }
    };

    match reviewer::write(&pack, &out) {
        Ok(side) => {
            let kb = (pack.size_bytes / 1024).max(1);
            println!(
                "Reviewer pack: {} ({kb} KB | {} focus | {} periphery | {} redaction(s))",
                out.display(),
                pack.focus_files.len(),
                pack.periphery_shown,
                pack.redactions
            );
            println!("Sidecar: {}", side.display());
            0
        }
        Err(e) => {
            eprintln!("c3 pack: {e}");
            1
        }
    }
}
//! `c3 explain` â€” build an explainer pack for one claim (milestone 7, D6). Because the
//! file leaves the machine, the redaction count and size are printed and an explicit
//! `--yes` or a `y/N` confirmation is required before it is written (D8). The pipeline
//! lives in [`crate::pack::explain`].

use std::io::Write;
use std::path::PathBuf;

use clap::Args;

use crate::pack::explain::{self, ExplainOpts};
use crate::providers;

/// Arguments of `c3 explain`.
#[derive(Args, Debug, Default)]
pub struct ExplainArgs {
    /// The claim to explain, verbatim (marked unverified in the pack).
    #[arg(long)]
    pub claim: String,
    /// Focus file(s): path or glob, in full with line numbers (repeatable).
    #[arg(long)]
    pub focus: Vec<String>,
    /// Token budget for the periphery (0 = none).
    #[arg(long, default_value_t = 0)]
    pub budget: usize,
    /// Who the explanation is for (free text).
    #[arg(long, default_value = "")]
    pub audience: String,
    /// Output path. Default: `<collab>/.c3/explains/<repo>_<ts>.md`.
    #[arg(long)]
    pub out: Option<String>,
    /// Skip the confirmation (the pack leaves the machine).
    #[arg(long)]
    pub yes: bool,
    /// Where consultations are stored; a relative path resolves against the repo root.
    #[arg(long, default_value = ".collab")]
    pub collab_dir: String,
}

/// Build the explainer pack, confirm, and write. Returns the process exit code.
pub fn run(args: ExplainArgs) -> i32 {
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let repo_root = providers::resolve_repo_root(&cwd);
    let collab_root = providers::resolve_collab_root(&repo_root, &args.collab_dir);

    let out = args
        .out
        .clone()
        .map(PathBuf::from)
        .unwrap_or_else(|| explain::default_out(&collab_root, &repo_root));

    let opts = ExplainOpts {
        repo_root,
        collab_root,
        claim: args.claim,
        focus: args.focus,
        budget: args.budget,
        audience: args.audience,
        max_file_size: 2 * 1024 * 1024,
    };

    let pack = match explain::build(&opts) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("c3 explain: {e}");
            return 1;
        }
    };

    let kb = (pack.size_bytes / 1024).max(1);
    let toks = if pack.tokens < 1000 {
        pack.tokens.to_string()
    } else {
        format!("{:.1}k", pack.tokens as f64 / 1000.0)
    };
    eprintln!(
        "Explainer pack ready: {} focus file(s), {} periphery, {kb} KB, ~{toks} tokens, {} redaction(s).",
        pack.focus_files.len(),
        pack.neighbours,
        pack.redactions
    );
    eprintln!(
        "This file will leave your machine when you share it. Destination: {}",
        out.display()
    );

    if !args.yes && !confirm() {
        eprintln!("c3 explain: aborted (no confirmation).");
        return 1;
    }

    match explain::write(&pack, &out) {
        Ok(()) => {
            println!("Explainer pack: {}", out.display());
            0
        }
        Err(e) => {
            eprintln!("c3 explain: {e}");
            1
        }
    }
}

/// Ask `y/N` on the terminal; default No. A non-tty / closed stdin reads as No.
fn confirm() -> bool {
    eprint!("Write it? [y/N] ");
    let _ = std::io::stderr().flush();
    let mut line = String::new();
    match std::io::stdin().read_line(&mut line) {
        Ok(_) => matches!(line.trim().to_ascii_lowercase().as_str(), "y" | "yes"),
        Err(_) => false,
    }
}
//! `c3 snapshot` â€” take a repository snapshot, optionally as a git delta (milestone 7).
