    };

    match snapshot::run(&opts) {
        Ok(r) => {
            let kb = (r.size_bytes / 1024).max(1);
            let toks = if r.tokens < 1000 {
                r.tokens.to_string()
            } else {
                format!("{:.1}k", r.tokens as f64 / 1000.0)
            };
            println!(
                "Snapshot: {} ({kb} KB | ~{toks} tokens | {} file(s) | {} redaction(s))",
                r.path.display(),
                r.files,
                r.redactions
            );
            0
        }
        Err(e) => {
            eprintln!("c3 snapshot: {e}");
            1
        }
    }
}
