554:         out.push_str("[timed out]");
555:     } else {
556:         match r.code {
557:             Some(c) => out.push_str(&format!("[exit code: {c}]")),
558:             None => out.push_str("[terminated without an exit code]"),
559:         }
560:     }
561:     out
562: }
