150: /// Build the event for one consultation, enqueue it to the spool (unless the environment
151: /// switch is off), and return the payload for the dry-run line. The call site in the
152: /// consult flow is wired by the coordinator; failures are ignored there.
153: pub fn record_consultation(
154:     entry: &LedgerEntry,
155:     panel_size: Option<u32>,
156: ) -> Result<serde_json::Value> {
157:     let event = Event::from_ledger(entry, panel_size, &instance_id());
158:     let payload = serde_json::to_value(&event)?;
159:     if !env_off() {
160:         default_spool().enqueue(&event)?;
161:     }
162:     Ok(payload)
163: }
164: 
165: // --------------------------------------------------------------------------- instance id
166: 
167: /// The stable, anonymous installation id: `sha256(salt + machine name)` where the salt is
168: /// 32 random bytes written once. Uses the default directory.
169: pub fn instance_id() -> String {
170:     instance_id_in(&telemetry_dir())
171: }
172: 
173: /// [`instance_id`] with an explicit directory (for tests): stable across calls in the same
174: /// directory, different for a different salt or machine.
175: pub fn instance_id_in(dir: &Path) -> String {
176:     let salt = read_or_create_salt(dir);
177:     let host = machine_name();
178:     let mut hasher = Sha256::new();
179:     hasher.update(salt.as_bytes());
180:     hasher.update(host.as_bytes());
181:     to_hex(&hasher.finalize())
182: }
183: 
184: /// Read the 64-hex-char salt, creating it (32 random bytes) once.
185: fn read_or_create_salt(dir: &Path) -> String {
186:     let path = dir.join("salt");
187:     if let Ok(existing) = std::fs::read_to_string(&path) {
188:         let trimmed = existing.trim();
189:         if !trimmed.is_empty() {
190:             return trimmed.to_string();
191:         }
192:     }
193:     // 32 bytes of randomness from two v4 UUIDs, stored as hex.
194:     let salt = format!("{}{}", Uuid::new_v4().simple(), Uuid::new_v4().simple());
195:     let _ = std::fs::create_dir_all(dir);
196:     let _ = std::fs::write(&path, &salt);
197:     salt
198: }
199: 
200: /// The machine name, from the same environment the reference client reads.
201: fn machine_name() -> String {
202:     std::env::var("COMPUTERNAME")
203:         .or_else(|_| std::env::var("HOSTNAME"))
204:         .unwrap_or_default()
205: }
